def calc_iso6346_check_digit(prefix: str, serial: str) -> int:
    """Calculate ISO 6346 check digit for a 4-alpha prefix and 6-digit serial."""
    chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    vals = {}
    v = 10
    for c in chars:
        if v in (11, 22, 33):
            v += 1
        vals[c] = v
        v += 1
    for i in range(10):
        vals[str(i)] = i

    code = prefix.upper() + str(serial)[:6].zfill(6)
    total = sum(vals.get(code[i], 0) * (2 ** i) for i in range(10))
    remainder = total % 11
    return 0 if remainder == 10 else remainder


def get_containertracking_metadata(container_num: str):
    """Resolve comprehensive metadata, carrier URLs, and modal info for containertracking.net."""
    cleaned = container_num.strip().upper()
    prefix = cleaned[:4]
    serial = cleaned[4:10] if len(cleaned) >= 10 else cleaned[4:]
    check_digit = cleaned[10] if len(cleaned) == 11 else ""

    expected_cd = calc_iso6346_check_digit(prefix, serial) if len(prefix) == 4 and len(serial) >= 6 else None

    pref_info = PREFIX_DB.get(prefix, {
        "prefix": prefix,
        "carrier": f"Shipping Line ({prefix})",
        "slug": prefix.lower(),
        "country": "International",
        "type": "Ocean Container",
    })

    slug = pref_info.get("slug", prefix.lower())
    c_info = CARRIER_INFO.get(slug, {})

    raw_track_url = c_info.get("track_url") or f"https://containertracking.net/track/{prefix.lower()}.html"
    track_url = raw_track_url.replace("{NUMBER}", cleaned)
    containertracking_url = f"https://containertracking.net/track/{prefix.lower()}.html"
    tracktainer_url = f"https://tracktainer.com/?container={cleaned}"

    return {
        "container_number": cleaned,
        "prefix": prefix,
        "serial": serial,
        "check_digit": check_digit,
        "calculated_check_digit": expected_cd,
        "is_check_digit_valid": str(expected_cd) == check_digit if check_digit and expected_cd is not None else True,
        "carrier_name": pref_info.get("carrier", f"Shipping Line ({prefix})"),
        "carrier_slug": slug,
        "country": pref_info.get("country", "International"),
        "equipment_type": pref_info.get("type", "Ocean Container"),
        "official_tracking_url": track_url,
        "containertracking_net_url": containertracking_url,
        "tracktainer_url": tracktainer_url,
        "allows_iframe": c_info.get("allows_iframe", False),
    }
